430	  // observable checkpoints below (Proxmox clone/config/start, guest-agent boot,
431	  // SSH reachability, and the game's own port opening). Never allowed to fail
432	  // the provision — it's purely a display aid, same discipline as worker/hosting.ts's
433	  // equivalent `step()`.
434	  const step = (label: string) =>
435	    db.server.update({ where: { id: server.id }, data: { provisioningStep: label } }).catch(() => undefined);
