454	    await sendReviewRequestForServer(server.id);
455	    return;
456	  }
457	
458	  const { conn, row: nodeRow } = await nodeFor(server);
459	  const storage = server.plan.storageTier === "hdd"
460	    ? nodeRow?.storageHdd ?? "vmdata-hdd"
461	    : nodeRow?.storageNvme ?? "vmdata";
462	
463	  // Pick a vmid that does NOT still own a previous tenant's backup archives.
464	  // `/cluster/nextid` hands back the lowest FREE id, and nothing reaps a deleted
465	  // server's vzdump archives, so the id freed by a deletion comes back carrying
466	  // the old owner's backups — which every backup surface then attributes to the
467	  // new customer (listBackups/requestRestore key on vmid alone). See
468	  // `pickProvisionVmid` in lib/proxmox.ts. Only for a FRESH allocation: a retry
469	  // keeps the vmid already persisted on the row.
