679	      // answers, but the game process itself may still be pulling its image and
680	      // starting its container before its own port opens — a real, observable
681	      // distinction (not present at all for a plain VPS order), unlike "pulling
682	      // the image" itself, which happens inside the guest's own cloud-init run
683	      // with no channel back to this worker to report on.
684	      await step("Starting the game server…");
685	      // `ip` is the dedicated public IP or the NAT server's private address —
686	      // already computed above. Checking against `ip` proves what this check
687	      // exists to prove: the game process itself bound its port, independent of
688	      // whether that port has been forwarded to the internet yet.
689	      const gameCheck = await checkGamePortOpen(ip, game.port, game.protocol);
690	      if (!gameCheck.ok) {
691	        throw new Error(
692	          `game port ${game.port}/${game.protocol} never opened on ${ip} after ` +
693	            `~${Math.round(gameCheck.elapsedMs / 1000)}s (${gameCheck.attempts} attempt(s); last error: ` +
694	            `${gameCheck.error}). SSH is up, but the game server itself never started listening, so this ` +
695	            `server cannot be handed to the customer as ready.`
696	        );
697	      }
